C("Validate the fragment for a tab: #tab- then an integer 1 through 32 with no leading zeros. No spaces or other text.",r"#tab-(?:[1-9]|[12][0-9]|3[0-2])","#tab-1|#tab-2|#tab-9|#tab-10|#tab-20|#tab-30|#tab-31|#tab-32","#tab-0|#tab-33|#tab-01|#tab-+1|#Tab-1|#tab-1.0", "A numeric fragment still has a bounded range.")
C("An internal host consists of a lowercase ASCII label 1 to 10 letters long followed by .test, optionally followed by :443. No scheme, slash, hyphens or other ports.",r"[a-z]{1,10}\.test(?::443)?","a.test|a.test:443|abcdefghij.test|abcdefghij.test:443|api.test|api.test:443|cdn.test|cdn.test:443",".test|abcdefghijk.test|A.test|aXtest|a.test:80|https://a.test|a-.test", "Only the explicit port is optional; the dot remains literal.")
C("The upload accept field is a comma-separated list of 1 to 4 lowercase extensions chosen from .png, .jpg and .webp. No spaces; repeated extensions are allowed.",r"\.(?:png|jpg|webp)(?:,\.(?:png|jpg|webp)){0,3}",".png|.jpg|.webp|.png,.jpg|.webp,.png,.jpg|.png,.png,.png,.png|.jpg,.webp|.webp,.webp,.webp,.webp","|.PNG|png|.gif|.png, .jpg|.png,.png,.png,.png,.png|.png,", "Count list entries and require every leading dot.")
